const HTML_ESCAPE_MAP = {
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#039;',
  '&': '&amp;'
} as const;

export function sanitizeInput(input: string): string {
  return input.replace(/[<>"'&]/g, (char) => HTML_ESCAPE_MAP[char as keyof typeof HTML_ESCAPE_MAP]);
}

